@orders_bp.route("/report", methods=["GET"])
def orders_report():
    key = get_api_key()
    if key is None:
        return jsonify({"error": "valid API key required"}), 401
    session = get_session()
    orders = session.query(Order).all()
    return jsonify({"order_count": len(orders), "revenue": sum(o.total for o in orders), "orders": [o.to_dict() for o in orders]})

def get_api_key() -> ApiKey | None:
    raw = request.headers.get("X-Api-Key", "")
    if not raw:
        return None
    session = get_session()
    return session.query(ApiKey).filter(ApiKey.key == raw).first()

